/**
 * HeatShield jury demo mode — SIMULATED DUMMY DATA.
 *
 * A deterministic (seeded) synthetic week: 13-19 July, Abu Dhabi,
 * 3 fictional crews, 54 fictional workers. Weather is generated by a
 * seeded PRNG and pushed through the SAME heat.js engine as live mode,
 * so every WBGT / tier / schedule number is internally consistent.
 * Compliance events are simulated with a fixed pattern per crew.
 *
 * Nothing here is a real worker, a real measurement, or a real outcome.
 * The UI labels this section "SIMULATED DUMMY DATA" at all times.
 */
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const DEMO_CREWS = [
  { id: "Alpha", site: "Mussafah — steel erection", workers: 24, workload: "moderate", acclimatised: true, complianceBase: 0.92 },
  { id: "Bravo", site: "Corniche — roadworks", workers: 18, workload: "heavy", acclimatised: true, complianceBase: 0.81 },
  { id: "Charlie", site: "Al Ain — landscaping (new crew)", workers: 12, workload: "moderate", acclimatised: false, complianceBase: 0.64 },
];

function generateDemoWeek(H) {
  const rand = mulberry32(20260713);
  const days = [];
  for (let d = 0; d < 7; d++) {
    const dayPeak = 42 + rand() * 3.5; // 42.0 - 45.5 C peak air temp
    const hours = [];
    for (let hr = 0; hr < 24; hr++) {
      const diurnal = Math.sin(((hr - 6) / 24) * 2 * Math.PI);
      const temp = dayPeak - 8 + 8 * Math.max(0, diurnal) + (rand() - 0.5) * 0.8;
      const rh = Math.min(85, Math.max(25, 68 - 22 * Math.max(0, diurnal) + (rand() - 0.5) * 6));
      const solar = hr >= 6 && hr <= 18 ? Math.max(0, 980 * Math.sin(((hr - 6) / 12) * Math.PI)) * (0.9 + rand() * 0.1) : 0;
      const wind = 6 + rand() * 8;
      const r = H.wbgtOutdoor(temp, rh, solar, wind);
      hours.push({ hour: hr, temp, rh, solar, wind, ...r });
    }
    days.push({ date: `July ${13 + d}`, hours });
  }

  // Per-crew aggregates over the working window 06:00-18:00
  const crews = DEMO_CREWS.map((crew, ci) => {
    let stopHours = 0, redOrWorse = 0, peakWbgt = 0, workHours = 0;
    for (const day of days) {
      for (const h of day.hours) {
        if (h.hour < 6 || h.hour >= 18) continue;
        const a = H.workRest(h.wbgt, crew.workload, crew.acclimatised);
        peakWbgt = Math.max(peakWbgt, h.wbgt);
        if (a.tier === "black") stopHours++;
        if (a.tier === "red" || a.tier === "black") redOrWorse++;
        workHours += a.workMin / 60;
      }
    }
    // Simulated compliance: deterministic jitter around the crew base rate
    const crank = mulberry32(900 + ci);
    const events = 84; // 12 scheduled rests/day x 7 days
    let taken = 0;
    for (let i = 0; i < events; i++) if (crank() < crew.complianceBase) taken++;
    return { ...crew, stopHours, redOrWorse, peakWbgt, workHours: Math.round(workHours), compliance: taken / events, restEvents: events, restsTaken: taken };
  });

  const totalWorkers = DEMO_CREWS.reduce((s, c) => s + c.workers, 0);
  const kpis = {
    workerDays: totalWorkers * 7,
    totalStopHours: crews.reduce((s, c) => s + c.stopHours, 0),
    totalRedOrWorse: crews.reduce((s, c) => s + c.redOrWorse, 0),
    avgCompliance: crews.reduce((s, c) => s + c.compliance * c.workers, 0) / totalWorkers,
    alertsIssued: crews.reduce((s, c) => s + c.redOrWorse, 0) * 1, // one alert per red/black crew-hour, simplified
    peakWbgt: Math.max(...crews.map((c) => c.peakWbgt)),
  };

  // Timeline: first STOP hour of each day for the most exposed crew (Bravo, heavy)
  const timeline = [];
  for (const day of days) {
    const firstBlack = day.hours.find((h) => h.hour >= 6 && h.hour < 18 && H.workRest(h.wbgt, "heavy", true).tier === "black");
    if (firstBlack)
      timeline.push({ when: `${day.date}, ${String(firstBlack.hour).padStart(2, "0")}:00`, what: `WBGT ${firstBlack.wbgt.toFixed(1)}°C — STOP called for Crew Bravo (heavy work), all crews to shade rest` });
  }
  timeline.push({ when: "July 15, 09:20", what: "Crew Charlie compliance fell below 70% — early-alert adaptation switched ON for Charlie (alerts fire one tier earlier)" });
  timeline.push({ when: "July 19, 18:00", what: "Week complete in the simulated log: no heat-illness incidents recorded; Charlie's early-alert adaptation stayed ON all week and a supervisor review was scheduled — low compliance is treated as a system signal, not a worker fault" });

  return { days, crews, kpis, timeline, totalWorkers };
}

const demoApi = { generateDemoWeek, DEMO_CREWS, mulberry32 };
if (typeof module !== "undefined" && module.exports) module.exports = demoApi;
if (typeof window !== "undefined") window.HeatDemo = demoApi;
